Add-Type -AssemblyName System.Drawing
$dir=(Get-Location).Path+'\public\assets\images\catalog';$files=Get-ChildItem -LiteralPath $dir -File;$map=@{};$groups=@{}
foreach($f in $files){try{$src=[Drawing.Bitmap]::new($f.FullName);$x=[int]($src.Width*.12);$y=[int]($src.Height*.04);$w=[int]($src.Width*.76);$h=[int]($src.Height*.70);$small=[Drawing.Bitmap]::new(6,6);$g=[Drawing.Graphics]::FromImage($small);$g.DrawImage($src.Clone([Drawing.Rectangle]::new($x,$y,$w,$h),[Drawing.Imaging.PixelFormat]::Format24bppRgb),0,0,6,6);$g.Dispose();$src.Dispose();$sig='';for($yy=0;$yy-lt6;$yy++){for($xx=0;$xx-lt6;$xx++){$c=$small.GetPixel($xx,$yy);$sig+=([math]::Floor($c.R/64)).ToString()+([math]::Floor($c.G/64)).ToString()+([math]::Floor($c.B/64)).ToString()}};$small.Dispose();$map[$f.Name]=$sig;if(!$groups.ContainsKey($sig)){$groups[$sig]=@()};$groups[$sig]+=$f.Name}catch{}}
$out=Join-Path (Get-Location) 'visual-body-buckets.json';$map|ConvertTo-Json -Compress|Set-Content -Encoding UTF8 $out;$dups=@($groups.Values|Where-Object Count -gt 1);$removed=($dups|ForEach-Object{$_.Count-1}|Measure-Object -Sum).Sum;Write-Output ('FILES '+$files.Count);Write-Output ('BUCKETS '+$groups.Count);Write-Output ('DUP_BUCKETS '+$dups.Count);Write-Output ('REMOVED '+$removed);$dups|Sort-Object Count -Descending|Select-Object -First 15|ForEach-Object{Write-Output ('GROUP '+($_ -join ', '))};Write-Output ('MAP '+$out)
